    #[doc = " Integer order of the [Bessel function](https://en.wikipedia.org/wiki/Bessel_function) of the first kind (f32)."] #[cfg_attr (assert_no_panic , no_panic :: no_panic)] pub fn jnf (n : i32 , mut x : f32) -> f32 { let mut ix : u32 ; let mut nm1 : i32 ; let mut sign : bool ; let mut i : i32 ; let mut a : f32 ; let mut b : f32 ; let mut temp : f32 ; ix = x . to_bits () ; sign = (ix >> 31) != 0 ; ix &= 0x7fffffff ; if ix > 0x7f800000 { return x ; } if n == 0 { return j0f (x) ; } if n < 0 { nm1 = - (n + 1) ; x = - x ; sign = ! sign ; } else { nm1 = n - 1 ; } if nm1 == 0 { return j1f (x) ; } sign &= (n & 1) != 0 ; x = fabsf (x) ; if ix == 0 || ix == 0x7f800000 { b = 0.0 ; } else if (nm1 as f32) < x { a = j0f (x) ; b = j1f (x) ; i = 0 ; while i < nm1 { i += 1 ; temp = b ; b = b * (2.0 * (i as f32) / x) - a ; a = temp ; } } else if ix < 0x35800000 { if nm1 > 8 { nm1 = 8 ; } temp = 0.5 * x ; b = temp ; a = 1.0 ; i = 2 ; while i <= nm1 + 1 { a *= i as f32 ; b *= temp ; i += 1 ; } b = b / a ; } else { let mut t : f32 ; let mut q0 : f32 ; let mut q1 : f32 ; let mut w : f32 ; let h : f32 ; let mut z : f32 ; let mut tmp : f32 ; let nf : f32 ; let mut k : i32 ; nf = (nm1 as f32) + 1.0 ; w = 2.0 * nf / x ; h = 2.0 / x ; z = w + h ; q0 = w ; q1 = w * z - 1.0 ; k = 1 ; while q1 < 1.0e4 { k += 1 ; z += h ; tmp = z * q1 - q0 ; q0 = q1 ; q1 = tmp ; } t = 0.0 ; i = k ; while i >= 0 { t = 1.0 / (2.0 * ((i as f32) + nf) / x - t) ; i -= 1 ; } a = t ; b = 1.0 ; tmp = nf * logf (fabsf (w)) ; if tmp < 88.721679688 { i = nm1 ; while i > 0 { temp = b ; b = 2.0 * (i as f32) * b / x - a ; a = temp ; i -= 1 ; } } else { i = nm1 ; while i > 0 { temp = b ; b = 2.0 * (i as f32) * b / x - a ; a = temp ; let x1p60 = f32 :: from_bits (0x5d800000) ; if b > x1p60 { a /= b ; t /= b ; b = 1.0 ; } i -= 1 ; } } z = j0f (x) ; w = j1f (x) ; if fabsf (z) >= fabsf (w) { b = t * z / b ; } else { b = t * w / a ; } } if sign { - b } else { b } }
